return ['domain'=>'zinn-chat','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'ne_NP','project-id-version'=>'zinn-chat','pot-creation-date'=>'2026-10-02T00:01:12+00:00','po-revision-date'=>'2026-10-02T00:01:12+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Chat'=>'Zinn® Chat','https://zinndigital.com/wordpress-plugins/zinn-chat'=>'https://zinndigital.com/wordpress-plugins/zinn-chat','A complete help desk and AI assistant that runs on your own WordPress: an AI that answers from your own pages with links, live chat, and support tickets in wp-admin, on a submit-a-ticket page and in the WooCommerce account area. Under 10 KB on the page and no requests at all until a visitor opens it.'=>'तपाईंको आफ्नै WordPress मा चल्ने एक पूर्ण हेल्प डेस्क र AI सहायक: एक AI जसले लिङ्कहरू, लाइभ च्याट, र wp-admin मा समर्थन टिकटहरू, टिकट पेस गर्ने पृष्ठमा र WooCommerce खाता क्षेत्रमा तपाईंकै पृष्ठहरूबाट उत्तर दिन्छ। पृष्ठमा १० किलोबाइटभन्दा कम र आगन्तुकले नखोलेसम्म कुनै पनि अनुरोध हुँदैन।','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Inbox'=>'इनबक्स','Tickets'=>'टिकटहरू','Assistant'=>'सहायक','Settings'=>'सेटिङहरू','Setup'=>'सेटअप','Zinn® Chat could not create its database tables:'=>'Zinn® Chat ले आफ्नो डाटाबेस तालिका सिर्जना गर्न सकेन:','The AI assistant could not answer a visitor:'=>'AI सहायकले आगन्तुकको प्रश्नको उत्तर दिन सकेन:','Fix it'=>'यसलाई ठीक गर्नुहोस्','Loading…'=>'लोड हुँदैछ…','This screen needs JavaScript.'=>'यो स्क्रिनलाई जाभास्क्रिप्ट आवश्यक छ।','Chat'=>'क्याट','AI assistant'=>'AI सहायक','Tickets and email'=>'टिकट र इमेल','Site index'=>'साइट अनुक्रमणिका','Privacy and spam'=>'गोपनीयता र स्प्याम','Connect to Zinn Digital®'=>'Zinn Digital® मा जडान गर्नुहोस्','AI agents (MCP)'=>'AI एजेन्टहरू (MCP)','Show the chat on the site'=>'साइटमा च्याट देखाउनुहोस्','Nothing appears on the site, and nothing is loaded, until this is ticked.'=>'यो चयन नगरिएसम्म साइटमा केही पनि देखिँदैन र केही पनि लोड हुँदैन।','Chat title'=>'क्याट शीर्षक','Greeting'=>'अभिवादन','The first thing a visitor sees.'=>'आगन्तुकले देख्ने पहिलो कुरा।','Greeting when nobody can answer'=>'कोही पनि उत्तर दिन नसक्दाको अभिवादन','Colour'=>'रङ्ग','Text colour on the colour'=>'रङमा पाठको रङ','Position'=>'स्थिति','Bottom, end side (right in left-to-right languages)'=>'तल, अन्त्यको भाग (बायाँबाट दायाँ लेखिने भाषाहरूमा दायाँ)','Bottom, start side'=>'तल, सुरुको छेउ','Offer "Talk to a person"'=>'"व्यक्तिसँग कुरा गर्नुहोस्" अफर गर्नुहोस्','Shown while somebody has the Inbox open and is not set to away.'=>'कसैले इनबक्स खोलेको बेला र टाढा छैन भन्ने सेट गरिएको बेला देखाइन्छ।','Hide the chat from your support team while they are signed in'=>'समर्थन टोली लगइन भएका बेला उनीहरूबाट कुराकानी लुकाउनुहोस्','Show "Powered by Zinn® Chat" under the chat'=>'चैटको तल "Powered by Zinn® Chat" देखाउनुहोस्','Optional. Off unless you turn it on.'=>'वैकल्पिक। तपाईंले चालू नगरेसम्म यो बन्द रहन्छ।','Let the AI assistant answer visitors'=>'आर्टिफिसियल इन्टेलिजेन्स (AI) सहायकलाई आगन्तुकहरूको जवाफ दिन दिनुहोस्','Assistant name'=>'सहायकको नाम','Extra instructions for the assistant'=>'सहायकका लागि अतिरिक्त निर्देशनहरू','For example: "Always mention our 30-day returns." They cannot override the safety rules.'=>'उदाहरणका लागि: "हाम्रो ३० दिने फिर्ता नीति सधैं उल्लेख गर्नुहोस्।" तिनीहरूले सुरक्षा नियमहरूलाई ओझेलमा पार्न सक्दैनन्।','Answer language'=>'उत्तर भाषा','"auto" answers in the visitor\'s own language; or a locale such as en_GB or de_DE to always answer in one language.'=>'"auto" ले आगन्तुकको आफ्नै भाषामा उत्तर दिन्छ; वा सधैँ एउटै भाषामा उत्तर दिन en_GB वा de_DE जस्तो लोकेल प्रयोग गर्नुहोस्।','Minimum relevance'=>'न्यूनतम प्रासंगिकता','Passages scoring below this (0 to 0.95) are not used, and the assistant says it does not know. Check scores in the test console.'=>'यसभन्दा कम (० देखि 0.95 सम्म) अङ्क प्राप्त गर्ने अंशहरू प्रयोग गरिँदैनन्, र सहायकले आफूलाई थाहा नभएको कुरा बताउँछ। परीक्षण कन्सोलमा अङ्कहरू जाँच गर्नुहोस्।','Offer a person after this many unanswered questions'=>'यति धेरै अनुत्तरित प्रश्नहरू पछि एक व्यक्तिलाई प्रस्ताव गर्नुहोस्','Longest answer (tokens)'=>'सबैभन्दा लामो उत्तर (टोकनहरू)','Accept support tickets'=>'समर्थन टिकटहरू स्वीकार गर्नुहोस्','Support page'=>'समर्थन पृष्ठ','The page with the [zinn_chat_support] shortcode or the Support page block. Ticket links in emails open this page.'=>'[zinn_chat_support] सर्टकोड वा समर्थन पृष्ठ ब्लक भएको पृष्ठ। इमेलहरूमा भएका टिकट लिङ्कहरूले यो पृष्ठ खोल्छन्।','Send team alerts to'=>'टोलीका चेतावनीहरू यसमा पठाउनुहोस्','One or more email addresses, separated by commas. Empty: the site admin email.'=>'एक वा बढी इमेल ठेगानाहरू, अल्पविरामद्वारा छुट्ट्याइएका। खाली: साइट प्रशासकको इमेल।','Sender name on emails'=>'इमेलहरूमा पठाउनेको नाम','Email the team when a visitor waits for a person longer than (minutes)'=>'जब आगन्तुकले व्यक्तिको लागि (मिनेट) भन्दा बढी पर्खन्छ भने टोलीलाई इमेल पठाउनुहोस्','Private ticket links work for (days after the last message)'=>'निजी टिकट लिङ्कहरू (पछिल्लो सन्देश पछिका दिनहरू) का लागि काम गर्छन्','After that the page offers to email a new link.'=>'त्यसपछि पृष्ठले नयाँ लिङ्क इमेल गर्ने विकल्प दिन्छ।','Add a Support tab to the WooCommerce account area'=>'WooCommerce खाता क्षेत्रमा समर्थन (Support) ट्याब थप्नुहोस्','Let the assistant tell signed-in customers about their own orders'=>'सहायकलाई साइन इन गरिसकेका ग्राहकहरूलाई उनीहरूका आफ्नै अर्डरहरूको बारेमा बताउन दिनुहोस्','Answers "where is my order?" from the order status and tracking.'=>'अर्डर स्थिति र ट्र्याकिङबाट "मेरो अर्डर कहाँ छ?" भन्ने जवाफ दिन्छ।','Content the assistant reads'=>'सहायकले पढ्ने सामग्री','None ticked means every public type.'=>'कुनै पनि चयन गरिएको छैन भने सबै सार्वजनिक प्रकारहरू भन्ने बुझिन्छ।','WooCommerce products, prices, stock, shipping and payment methods'=>'WooCommerce उत्पादनहरू, मूल्यहरू, स्टक, ढुवानी र भुक्तानी विधिहरू','Forums (bbPress, BuddyBoss, wpForo)'=>'फञ्चमहरू (bbPress, BuddyBoss, wpForo)','Read pages as visitors see them when a page builder\'s content cannot be read directly'=>'पृष्ठ निर्माणकर्ताको सामग्री प्रत्यक्ष रूपमा पढ्न नसकिँदा आगन्तुकहरूले देखेअनुसारका पृष्ठहरू पढ्नुहोस्','Fetches the page from your own site in the background.'=>'यसले पृष्ठलाई पृष्ठभूमिमा तपाईंको आफ्नै साइटबाट ल्याउँछ।','Never read these posts or pages (IDs)'=>'यी पोस्टहरू वा पेजहरू (IDs) कहिल्यै नपढ्नुहोस्','Comma-separated.'=>'अल्पविरामद्वारा-विभाजित।','Ask visitors to agree before a chat or ticket'=>'चैट वा टिकट अघि आगन्तुकहरूलाई सहमत हुन भन्नुहोस्','Agreement text'=>'सम्झौता पाठ','Privacy policy link'=>'गोपनीयता नीति लिङ्क','Empty: the site\'s privacy policy page.'=>'खाली: साइटको गोपनीयता नीति पृष्ठ।','Delete finished chats and tickets after (days)'=>'समाप्त भएका च्याट र टिकटहरू (दिनहरू) पछि मेटाउनुहोस्','0 keeps them.'=>'0 ले तिनीहरूलाई राख्छ।','Store visitors\' IP addresses'=>'भिजिटरहरूको IP ठेगानाहरू सुरक्षित गर्नुहोस्','Off: only a coded form is kept, enough for spam limits.'=>'बन्द: स्पाम सीमाहरूको लागि मात्र पर्याप्त कोड गरिएको रूप राखिएको छ।','Messages per visitor per hour'=>'प्रति आगन्तुक प्रति घण्टा सन्देशहरू','Chats per visitor per day'=>'प्रति आगन्तुक प्रति दिन च्याटहरू','Tickets per visitor per day'=>'प्रति आगन्तुक प्रति दिन टिकटहरू','Longest chat message (characters)'=>'सबभन्दा लामो च्याट सन्देश (वर्णहरू)','Block list'=>'ब्लक सूची','One per line: an IP address, an email address, @domain.com, or a word.'=>'प्रत्येक लाइनमा एक: IP ठेगाना, इमेल ठेगाना, @domain.com, वा एउटा शब्द।','Where chats are answered'=>'च्याटहरूको उत्तर दिइने ठाउँ','"This site" keeps everything in this site\'s database and uses your own AI key. "Zinn Digital®" uses the hosted inbox in the Zinn® app (for Zinn® hosting customers).'=>'"यो साइट" ले यस साइटको डेटाबेसका सबै कुरा राख्छ र तपाईंको आफ्नै एआई कुञ्जी प्रयोग गर्दछ। "Zinn Digital®" ले Zinn® एपमा (Zinn® होस्टिङ ग्राहकहरूका लागि) होस्ट गरिएको इनबक्स प्रयोग गर्दछ।','This site (recommended)'=>'यो साइट (सिफारिस गरिएको)','Zinn Digital® app'=>'Zinn Digital® एप','Zinn® widget key'=>'Zinn® विजेट कुञ्जी','From the Zinn® app: Live chat, then your widget. Starts with zc_.'=>'Zinn® एपबाट: लाइभ च्याट, त्यसपछि तपाईंको विजेट। zc_ बाट सुरु हुन्छ।','Allow AI agents (MCP)'=>'AI एजेन्टहरूलाई अनुमति दिनुहोस् (MCP)','Off: the tools below and their REST routes are not registered at all.'=>'बन्द: तलका उपकरणहरू र तिनीहरूका REST रुटहरू पटक्कै दर्ता भएका छैनन्।','Zinn® Chat settings'=>'Zinn® Chat सेटिङहरू','Settings saved.'=>'setting सुरक्षित गरियो।','The assistant uses your own AI key.'=>'सहयोगीले तपाईंको आफ्नै AI कुञ्जी प्रयोग गर्दछ।','AI providers and models'=>'AI प्रदायकहरू र मोडेलहरू','— None —'=>'— कुनै पनि होइन —','Saved — leave empty to keep'=>'बचत भयो — राख्नका लागि खाली छोड्नुहोस्','Remove the saved key'=>'सुरक्षित गरिएको कुञ्जी हटाउनुहोस्','You are not allowed to change these settings.'=>'तपाईंलाई यी सेटिङहरू परिवर्तन गर्ने अनुमति छैन।','Turn the chat on'=>'च्याट अन गर्नुहोस्','The chat is showing on your site.'=>'तपाईंको साइटमा च्याट देखाइरहेको छ।','Nothing is shown or loaded on your site until you turn it on.'=>'तपाईंले यसलाई अन नगरेसम्म तपाईंको साइटमा केही पनि देखाइँदैन वा लोड हुँदैन।','Turn off'=>'बन्द गर्नुहोस्','Turn on'=>'सुरु गर्नुहोस्','Connect your AI provider'=>'तपाईंको AI प्रदायक जडान गर्नुहोस्','Connected. Site search uses %1$s (%2$s).'=>'जडान भयो। साइट खोजीले %1$s (%2$s) प्रयोग गर्छ।','Connected. Your provider cannot build a meaning-based index, so the assistant uses keyword search. Add a Google Gemini, OpenAI, Mistral or OpenRouter key for better answers.'=>'जडान भयो। तपाईँको प्रदायकले अर्थमा आधारित इन्डेक्स बनाउन सक्दैन, त्यसैले सहायकले किवर्ड खोज प्रयोग गर्दछ। राम्रो उत्तरका लागि Google Gemini, OpenAI, Mistral वा OpenRouter कुञ्जी थप्नुहोस्।','Add a key for Google Gemini, OpenAI, Anthropic Claude, Mistral, OpenRouter or any OpenAI-compatible service. The newest model is chosen for you; you can change it.'=>'Google Gemini, OpenAI, Anthropic Claude, Mistral, OpenRouter वा कुनै पनि OpenAI-अनुकूल सेवाका लागि कुञ्जी थप्नुहोस्। नयाँ मोडल तपाइँको लागि छनौट गरिएको छ; तपाइँ यसलाई परिवर्तन गर्न सक्नुहुन्छ।','AI providers'=>'AI प्रदायकहरू','Let the assistant read your site'=>'सहायकलाई तपाईंको साइट पढ्न दिनुहोस्','%1$d pages read, %2$d waiting, %3$d passages. New and edited content is picked up automatically.'=>'%1$d पृष्ठहरू पढिए, %2$d प्रतीक्षामा, %3$d अनुच्छेदहरू। नयाँ र सम्पादित सामग्री स्वतः प्राप्त हुन्छ।','Read the whole site now'=>'पूरा साइट अहिले नै पढ्नुहोस्','Create your support page'=>'तपाईंको सहयोग पृष्ठ सिर्जना गर्नुहोस्','Visitors submit tickets there, and ticket emails link to it.'=>'आगन्तुकहरूले त्यहाँ टिकटहरू पेश गर्छन्, र टिकट इमेलहरूले यसमा लिङ्क गर्छन्।','A page with the ticket form, where customers also follow their requests.'=>'टिकट फारम भएको एक पृष्ठ, जहाँ ग्राहकहरूले आफ्ना अनुरोधहरू पनि पछ्याउँछन्।','View'=>'हेर्नुहोस्','Create the support page'=>'समर्थन पृष्ठ सिर्जना गर्नुहोस्','Add "Submit a ticket" and "Chat with us" to a menu'=>'मेनुमा "टिकट पेस गर्नुहोस्" र "हामीसँग कुराकानी गर्नुहोस्" थप्नुहोस्','Appearance, Menus: use the Zinn® Chat box. Or add the Zinn® Chat blocks to any page, in any page builder.'=>'रूप, मेनुहरू: Zinn® Chat बाकस प्रयोग गर्नुहोस्। वा कुनै पनि पृष्ठ बिल्डरमा कुनै पनि पृष्ठमा Zinn® Chat ब्लकहरू थप्नुहोस्।','Menus'=>'मेनुहरू','WooCommerce account area'=>'WooCommerce खाता क्षेत्र','Customers see their tickets under Support in My Account, and the assistant can tell them where their order is.'=>'ग्राहकहरूले आफ्नो खातामा सहयोग अन्तर्गत आफ्ना टिकटहरू देख्न सक्छन्, र सहायकले उनीहरूलाई तिनीहरूको अर्डर कहाँ छ भनेर बताउन सक्छ।','Test the assistant'=>'सहायकको परीक्षण गर्नुहोस्','Ask it questions and see exactly which pages it answered from, including out-of-date ones.'=>'यसलाई प्रश्नहरू सोध्नुहोस् र यसले ठ्याक्कै कुन पृष्ठहरूबाट उत्तर दियो हेर्नुहोस्, जसमा पुराना भइसकेका पृष्ठहरू पनि समावेश छन्।','Open the test console'=>'परीक्षण कन्सोल खोल्नुहोस्','Answer live chats'=>'लाइभ च्याटहरूको उत्तर दिनुहोस्','Visitors can ask for a person while you have the Inbox open. It works on a phone too.'=>'तपाईंको इनबक्स खुला हुँदा आगन्तुकहरूले कुनै व्यक्तिको बारेमा सोध्न सक्छन्। यो फोनमा पनि काम गर्छ।','Open the Inbox'=>'इनबक्स खोल्नुहोस्','Set up Zinn® Chat'=>'Zinn® Chat सेटअप गर्नुहोस्','This site is connected to the Zinn Digital® app: chats are answered there. To run the help desk on this site instead, choose "This site" under Settings, Connect to Zinn Digital®.'=>'यो साइट Zinn Digital® एपमा जडान गरिएको छ: च्याटहरूको उत्तर त्यहीं दिइन्छ। यसको सट्टा यो साइटमा मद्दत डेस्क चलाउन, सेटिङहरू अन्तर्गत "यो साइट" छान्नुहोस्, Zinn Digital® मा जडान गर्नुहोस्।','You are not allowed to do that.'=>'तपाईंलाई यो गर्न अनुमति छैन।','Unlimited agents, with a Support agent role that sees only chats and tickets'=>'असिम एजेन्टहरू, समर्थन एजेन्ट भूमिका सहित जसले च्याट र टिकटहरू मात्र देख्न सक्छ','Reply to tickets by email'=>'इमेल मार्फत टिकटहरूको जवाफ दिनुहोस्','Knowledge base: articles, categories, search, and a KB section in the chat'=>'ज्ञानकोश: लेखहरू, वर्गहरू, खोजी, र च्याटमा एक केबी खण्ड','Saved replies, business hours, priorities and SLAs'=>'सेभ गरिएका उत्तरहरू, व्यापारिक समय, प्राथमिकताहरू र SLA हरू','Suggested replies, thread summaries and auto-tagging by AI'=>'एआईद्वारा सुझाएका प्रत्यउत्तरहरू, थ्रेड सारांशहरू र स्वतः-ट्यागिङ','Knowledge-gap report: the questions your site could not answer'=>'ज्ञान-अन्तर प्रतिवेदन: तपाईँको साइटले उत्तर दिन नसकेका प्रश्नहरू','Push notifications and an installable agent app for your phone'=>'तपाईंको फोनको लागि पुश सूचनाहरू र स्थापना गर्न मिल्ने एजेन्ट एप','Proactive messages, reports, webhooks, Slack and Telegram alerts'=>'सक्रिय सन्देशहरू, प्रतिवेदनहरू, वेबहुकहरू, Slack र Telegram चेतावनीहरू','Zinn® Chat Pro'=>'Zinn® Chat प्रो','From $%1$d a month or $%2$d a year for one site.'=>'एउटा साइटका लागि प्रतिमहिना $%1$d वा प्रतिवर्ष $%2$d बाट सुरु हुन्छ।','Try Pro free for 14 days'=>'प्रो (Pro) लाई १४ दिनका लागि निःशुल्क प्रयास गर्नुहोस्','See plans'=>'योजनाहरू हेर्नुहोस्','No card needed for the trial.'=>'परीक्षणका लागि कार्ड आवश्यक छैन।','The makers of ChatGPT. A good all-rounder.'=>'ChatGPT का निर्माताहरू। एक राम्रो सर्वाङ्गीण।','The makers of Claude. Strong at writing and careful reasoning.'=>'Claude का निर्माताहरू। लेखन र तार्किक तर्कमा सक्षम।','Google\'s Gemini models. Fast and inexpensive.'=>'Google को Gemini मोडलहरू। छिटो र किफायती।','A European AI company with fast, inexpensive models.'=>'छिटो र किफायती मोडेलहरू भएको एक युरोपेली AI कम्पनी।','Low-cost models that are good at writing and code.'=>'लेखन र कोडिङमा राम्रा कम लागतका मोडेलहरू।','One key for models from many different providers.'=>'धेरै विभिन्न प्रदायकहरूका मोडलहरूका लागि एउटा मुख्य चाबी।','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'तपाईंको आफ्नै कम्प्युटर वा सर्भरमा चलिरहेको मोडल लगायत OpenAI को API जस्तै काम गर्ने कुनै पनि सेवा।','General (used when nothing more specific is set)'=>'सामान्य (कुनै विशिष्ट कुरा सेट नभएको बेला प्रयोग हुने)','Writing and rewriting'=>'लेखन र पुनरालेखन','Translation'=>'अनुवाद','Code and CSS'=>'कोड र सीएसएस','Sorry, you are not allowed to access this page.'=>'माफ गर्नुहोला, तपाईंलाई यो पृष्ठ पहुँच गर्ने अनुमति छैन।','These settings are shared by every plugin that uses them: %s.'=>'यी सेटिङहरू तिनीहरूलाई प्रयोग गर्ने हरेक प्लगइनद्वारा साझा गरिएका छन्: %s।','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'तपाईंको कुञ्जीहरू यस साइटको डाटाबेसमा इन्क्रिप्ट गरिएका छन् र तपाईंले छान्नु भएको प्रदायकलाई मात्र पठाइन्छ — हामीलाई कहिल्यै पनि पठाइँदैन।','Step 1 of 2: choose an AI provider'=>'चरण १ को २: एआई प्रदायक छान्नुहोस्','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'तपाईं आफ्नो साँचो आफैं ल्याउनुहुन्छ, त्यसैले तपाईंले प्रयोग गर्नुभएको कुराको लागि प्रदायकलाई सिधै भुक्तानी गर्नुहुन्छ। निश्चित हुनुहुन्न? यीमध्ये कुनै पनि राम्रोसँग काम गर्छ; तपाईंले पछि थप थप्न सक्नुहुन्छ।','Next'=>'अर्को','Step 2 of 2: connect %s'=>'चरण २ को २: %s जडान गर्नुहोस्','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'/v1 मा अन्त्य हुने आफ्नो OpenAI-compatible सेवाको ठेगाना प्रविष्ट गर्नुहोस्। सेवाले मागेको अवस्थामा मात्र कुञ्जी (key) आवश्यक पर्दछ।','Open %s and sign in (or create a free account).'=>'%s खोल्नुहोस् र लग इन गर्नुहोस् (वा निःशुल्क खाता सिर्जना गर्नुहोस्)।','the %s API keys page'=>'%s API कुञ्जीहरूको पृष्ठ','Create a new key and copy it.'=>'नयाँ कुञ्जी सिर्जना गर्नुहोस् र यसलाई प्रतिलिपि गर्नुहोस्।','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'यसलाई तल टाँस्नुहोस् र "Save and test" मा थिच्नुहोस्। यो काम गर्छ कि गर्दैन भनेर जाँच गर्न हामी एउटा सानो अनुरोध पठाउँछौं।','Most providers need a little credit on the account before a key works: %s.'=>'धेरैजसो प्रदायकहरूलाई कुञ्जी (key) काम गर्नु अघि खातामा केही क्रेडिट आवश्यक पर्छ: %s।','add credit'=>'क्रेडिट थप्नुहोस्','← Choose a different provider'=>'← फरक प्रदायक छान्नुहोस्','Address'=>'ठेगाना','Saved key ends in …%s — paste a new one to replace it'=>'सुरक्षित गरिएको कुञ्जी …%s मा समाप्त हुन्छ — यसलाई बदल्न नयाँ टाँस्नुहोस्','Key (optional)'=>'कुञ्जी (ऐच्छिक)','API key'=>'API कुञ्जी','Save and test'=>'सेभ गर्नुहोस् र परीक्षण गर्नुहोस्','Providers'=>'प्रदायकहरू','Provider'=>'प्रदायक','Status'=>'स्थिति','Key'=>'कुञ्जी','Get a key'=>'कुञ्जी प्राप्त गर्नुहोस्','Test'=>'परीक्षण','Remove'=>'हटाउनुहोस्','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'नयाँ प्लगइन संस्करणद्वारा सुरक्षित: यो प्लगइन अपडेट गर्नुहोस्, वा कुञ्जी फेरि प्रविष्ट गर्नुहोस्।','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'सुरक्षित गरिएको कुञ्जी अब खोल्न सकिँदैन (साइटको सुरक्षा कुञ्जीहरू परिवर्तन भएका छन्)। यसलाई फेरि प्रविष्ट गर्नुहोस्।','Not connected'=>'जडित छैन','Connected — last test passed %s'=>'जडित — अन्तिम परीक्षण उत्तीर्ण भयो %s','Last test failed: %s'=>'अन्तिम परीक्षण असफल भयो: %s','Connected — not tested yet'=>'जडित — परीक्षण गरिएको छैन','Which model to use'=>'कुन मोडेल प्रयोग गर्ने','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ ले त्यो कार्यका लागि हाम्रो सिफारिसलाई जनाउँछ। सूचीमा तपाईंको कुञ्जीले प्रयोग गर्न सक्ने हरेक मोडेल समावेश छ, जुन प्रदायकबाट प्रत्यक्ष रूपमा पढिन्छ।','— Recommended for the provider —'=>'— प्रदायकका लागि सिफारिस गरिएको —','Save models'=>'मोडलहरू सुरक्षित गर्नुहोस्','Refresh the model lists from the providers'=>'प्रदायकहरूबाट मोडेल सूचीहरू रिफ्रेस गर्नुहोस्','Images'=>'तस्बिरहरू','Connect OpenAI or Google Gemini to make images.'=>'तस्वीरहरू बनाउन OpenAI वा Google Gemini जडान गर्नुहोस्।','— The newest image model of the first connected provider —'=>'— पहिलो जडित प्रदायकको नवीनतम छवि मोडेल —','Site search (embeddings)'=>'साइट खोज (इम्बेडिङहरू)','Connect Google Gemini, OpenAI, Mistral or OpenRouter to build a search index of your site.'=>'तपाईंको साइटको खोजी अनुक्रमणिका (सर्च इन्डेक्स) निर्माण गर्न Google Gemini, OpenAI, Mistral वा OpenRouter जडान गर्नुहोस्।','— The newest embedding model of the first connected provider —'=>'— पहिलो जडित प्रदायकको सबैभन्दा नयाँ इम्बेडिङ मोडल —','Changing this rebuilds the search index of every plugin that uses it.'=>'यसलाई परिवर्तन गर्दा यसलाई प्रयोग गर्ने प्रत्येक प्लगइनको खोज अनुक्रमणिका (सर्च इन्डेक्स) पुन: निर्माण हुन्छ।','best quality'=>'सर्वोत्तम गुणस्तर','lowest cost'=>'न्यूनतम लागत','fastest'=>'सबभन्दा छिटो','Add a model yourself'=>'आफैं एक मोडेल थप्नुहोस्','A model came out today? Paste its exact name to use it straight away.'=>'आज एउटा नयाँ मोडल आएको छ? यसलाई तुरुन्तै प्रयोग गर्न यसको ठ्याक्कै नाम पेस्ट गर्नुहोस्।','Model name'=>'मोडेलको नाम','Add model'=>'मोडेल थप्नुहोस्','Recommended models list'=>'सिफारिस गरिएका मोडेलहरूको सूची','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'सिफारिस गरिएका मोडलहरूको सूची प्रमाणीकरण गर्न सकिएन, त्यसैले कुनै पनि सिफारिसहरू देखाइएको छैन। प्लगइन पुन: इन्स्टल गर्नुहोस्, वा तलका दैनिक अपडेटहरू चालू गर्नुहोस्।','The list in use was published on %s. Each plugin update brings a fresh one.'=>'प्रयोगमा रहेको सूची %s मा प्रकाशित गरिएको थियो। प्रत्येक प्लगइन अपडेटले नयाँ सूची ल्याउँछ।','Also check Zinn Digital® once a day for an updated list.'=>'अद्यावधिक गरिएको सूचीका लागि दिनको एक पटक Zinn Digital® पनि जाँच गर्नुहोस्।','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'एउटा सामान्य डाउनलोड अनुरोध मात्र पठाइन्छ: कुनै कुञ्जी छैन, कुनै साइट ठेगाना छैन, तपाईंको सामग्रीको बारेमा केही छैन। सूचीमा हस्ताक्षर गरिएको हुन्छ, र हस्ताक्षर जाँचमा असफल हुने सूचीलाई बेवास्ता गरिन्छ।','Last checked %1$s: %2$s.'=>'पछिल्लो पटक जाँच गरिएको %1$s: %2$s।','Save, and check now if turned on'=>'बचत गर्नुहोस्, र यदि चालु गरिएको छ भने अहिले जाँच गर्नुहोस्','a newer list was installed'=>'एउटा नयाँ सूची स्थापना गरियो','already up to date'=>'पहिले नै अप-टु-डेट छ','the download failed the signature check and was ignored'=>'डाउनलोडले हस्ताक्षर जाँचमा असफल भयो र यसलाई बेवास्ता गरियो','Zinn Digital® could not be reached; the current list stays in use'=>'Zinn Digital® लाई सम्पर्क गर्न सकिएन; हालको सूची प्रयोगमा रहन्छ','turned off'=>'बन्द गरिएको','Open'=>'खोल्नुहोस्','Check their status page'=>'तिनीहरूको स्थिति पृष्ठ जाँच गर्नुहोस्','Open your billing page'=>'तपाईंको बिलिङ पृष्ठ खोल्नुहोस्','Open your API keys page'=>'तपाईंको API कुञ्जीहरूको पृष्ठ खोल्नुहोस्','Open the AI settings'=>'AI सेटिङहरू खोल्नुहोस्','Sorry, you are not allowed to do that.'=>'माफ गर्नुहोस्, तपाईँलाई यो गर्न अनुमति छैन।','Unknown provider.'=>'अज्ञात प्रदायक।','Enter the address of your service, for example http://localhost:11434/v1.'=>'तपाईंको सेवाको ठेक्का प्रविष्ट गर्नुहोस्, उदाहरणका लागि http://localhost:11434/v1।','That does not look like an API key. Copy it again, without spaces.'=>'त्यो API कुञ्जी जस्तो देखिंदैन। यसलाई खाली ठाउँ बिना फेरि प्रतिलिपि गर्नुहोस्।','Paste your API key first.'=>'पहिले आफ्नो API कुञ्जी टाँस्नुहोस्।','Key removed.'=>'कुञ्जी हटाइयो।','Models saved.'=>'मोडलहरू सुरक्षित गरियो।','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'मोडेलको सटीक नाम प्रविष्ट गर्नुहोस्, उदाहरणका लागि प्रदायकको कागजातमा लेखिए अनुसार।','Added %s. Choose it under "Which model to use".'=>'%s थपियो। यसलाई "कुन मोडल प्रयोग गर्ने" अन्तर्गत छान्नुहोस्।','Model removed.'=>'मोडल हटाइयो।','Daily updates are off. The list that came with the plugin is used.'=>'दैनिक अपडेटहरू बन्द छन्। प्लगइनमा आएको सूची प्रयोग गरिएको छ।','Checked: %s.'=>'जाँच गरिएको: %s।','Model lists refreshed.'=>'मोडेल सूचीहरू ताजा गरियो।','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'तपाईंको एआई कुञ्जी तपाईंका प्लगइनहरू मध्ये एकको नयाँ संस्करणद्वारा सेभ गरिएको थियो। यो प्लगइन अपडेट गर्नुहोस्, वा एआई सेटिङहरूमा कुञ्जी फेरि प्रविष्ट गर्नुहोस्।','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'तपाईंको सुरक्षित गरिएको AI कुञ्जी अब खोल्न सकिँदैन (साइटको सुरक्षा कुञ्जीहरू परिवर्तन भएका छन्)। यसलाई AI सेटिङहरूमा फेरि प्रविष्ट गर्नुहोस्।','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'AI अहिलेसइज सेट अप गरिएको छैन। AI सेटिङहरूमा AI प्रदायकको कुञ्जी थप्नुहोस्।','No model is chosen for this task. Pick one in the AI settings.'=>'यस कार्यका लागि कुनै पनि मोडल छनौट गरिएको छैन। एआई सेटिङहरूमा एउटा छान्नुहोस्।','That AI provider is not supported by this version of the plugin.'=>'प्लगइनको यो संस्करणद्वारा त्यो AI प्रदायक समर्थित छैन।','No AI provider that can make images is connected. Add an OpenAI or Google Gemini key in the AI settings.'=>'तस्बिरहरू बनाउन सक्ने कुनै पनि AI प्रदायक जडान गरिएको छैन। AI सेटिङहरूमा OpenAI वा Google Gemini कुञ्जी थप्नुहोस्।','This AI provider cannot make images. Choose OpenAI or Google Gemini for images in the AI settings.'=>'यो AI प्रदायकले तस्बिरहरू बनाउन सक्दैन। AI सेटिङहरूमा तस्बिरहरूको लागि OpenAI वा Google Gemini रोज्नुहोस्।','Your AI key cannot use any image model. Check the key\'s permissions with the provider, or choose another provider for images.'=>'तपाईंको AI कुञ्जीले कुनै पनि छवि मोडेल प्रयोग गर्न सक्दैन। प्रदायकसँग कुञ्जीको अनुमतिहरू जाँच गर्नुहोस्, वा छविहरूको लागि अर्को प्रदायक छान्नुहोस्।','No connected AI provider can build a search index. Add a Google Gemini, OpenAI, Mistral or OpenRouter key in the AI settings.'=>'कुनै पनि जडान गरिएको AI प्रदायकले खोज इन्डेक्स निर्माण गर्न सक्दैन। AI सेटिङहरूमा Google Gemini, OpenAI, Mistral वा OpenRouter कुञ्जी थप्नुहोस्।','Your AI key cannot use any embedding model. Check the key\'s permissions with the provider, or choose another provider for site search.'=>'तपाईंको एआई कुञ्जीले कुनै पनि एम्बेडिङ मोडल प्रयोग गर्न सक्दैन। प्रदायकसँग कुञ्जीको अनुमतिहरू जाँच गर्नुहोस्, वा साइट खोजको लागि अर्को प्रदायक छान्नुहोस्।','This AI provider cannot build a search index. Connect Google Gemini, OpenAI, Mistral or a compatible service for site search.'=>'यो AI प्रदायकले खोज इन्डेक्स निर्माण गर्न सक्दैन। साइट खोजका लागि Google Gemini, OpenAI, Mistral वा मिल्दो सेवा जडान गर्नुहोस्।','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'यो साइट तपाईंको AI सेवामा पुग्न सकेन। यो चलिरहेको छ कि छैन र यसको ठेगाना तपाईंको वेब सर्भरबाट पहुँचयोग्य छ कि छैन भनी जाँच गर्नुहोस् (तपाईंको आफ्नै कम्प्युटरमा रहेको सेवा होस्ट गरिएको साइटबाट पहुँचयोग्य हुँदैन)।','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'यो साइटले %s मा पहुँच गर्न सकेन। तिनीहरूको स्थिति पृष्ठ जाँच गर्नुहोस्; यदि तिनीहरू अनलाइन छन् भने, तपाईंको होस्टले बाहिरी जडानहरू रोकिरहेको हुन सक्छ, वा ठेगाना गलत छ।','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s ले भन्छ कि तपाईंको खातामा कुनै क्रेडिट वा कोटा बाँकी छैन। उनीहरूसँगको तपाईंको खातामा क्रेडिट थप्नुहोस् या सीमा बढाउनुहोस्, त्यसपछि फेरि प्रयास गर्नुहोस्।','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s ले तपाईंको कुञ्जी स्वीकार गरेन। यो गलत टाइप भएको, खारेज गरिएको वा म्याद समाप्त भएको हुन सक्छ। नयाँ कुञ्जी सिर्जना गर्नुहोस् र यसलाई यहाँ टाँस्नुहोस्।','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s ले तपाईंको कुञ्जीका लागि यो अनुरोध अस्वीकार गर्‍यो। कुञ्जीसँग यो मोडेल वा सुविधामा पहुँच नभएको हुन सक्छ, वा तपाईंको खाता प्रमाणित गर्नुपर्ने हुन सक्छ।','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'तपाईंको कुञ्जीका लागि %2$s बाट "%1$s" मोडेल उपलब्ध छैन। AI सेटिङहरूमा अर्को मोडेल छान्नुहोस्।','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'तपाईंको %2$s योजनामा ​​"%1$s" मोडल समावेश छैन। AI सेटिङहरूमा अर्को मोडल छान्नुहोस्, वा उनीहरूसँग आफ्नो योजना अपग्रेड गर्नुहोस्।','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s ले तपाईंको कुञ्जीले अनुरोधहरू पठाउने गतिलाई सीमित गर्दैछ। एक मिनेट पर्खनुहोस् र पुनः प्रयास गर्नुहोस्, वा तिनीहरूसँग आफ्नो दर सीमा (rate limit) बढाउनुहोस्।','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s मा अहिले समस्या भइरहेको छ (उनीहरूकोतर्फबाट सेवा अवरोध वा अत्यधिक भार)। तपाईंको सेटिङमा कुनै समस्या छैन। छिट्टै फेरि प्रयास गर्नुहोस्।','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'AI अनुरोध असफल भयो जसको कारण हामी पहिचान गर्न सकेनौं। फेरि प्रयास गर्नुहोस्; यदि यो भइरह्यो भने, तलका विवरणहरूसँग समर्थन टोलीलाई सम्पर्क गर्नुहोस्।','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'AI प्रदायकले यो प्लगइनले पढ्न नसक्ने रूपमा उत्तर दियो। फेरि प्रयास गर्नुहोस्; यदि यो भइरहनुभयो भने, अर्को मोडेल छान्नुहोस् वा सहयोग टोलीलाई सम्पर्क गर्नुहोस्।','Custom (OpenAI-compatible)'=>'कस्टम (OpenAI-compatible)','Save a key for this provider first.'=>'पहिले यो प्रदायकका लागि कुञ्जी सुरक्षित गर्नुहोस्।','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'तपाईंको कुञ्जीले काम गर्छ, तर प्रदायकले यसको लागि कुनै पाठ मोडेल सूचीबद्ध गरेको छैन। तल आफैं एउटा मोडेल थप्नुहोस्।','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'जडान भयो। %1$s ले %2$s प्रयोग गरेर उत्तर दिनुभयो। तपाईंका AI सुविधाहरू प्रयोगका लागि तयार छन्।','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'तपाईंको प्रयोगकर्ता भूमिकालाई यो साइटमा एआई प्रयोग गर्ने अनुमति छैन। एक प्रशासकलाई सोध्नुहोस्।','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'यो साइटले यसको मासिक AI खर्च सीमा पुगेको छ। एक प्रशासकले यसलाई AI सेटिङहरूमा बढाउन सक्नुहुन्छ।','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'यो साइटले AI अनुरोधहरूको आफ्नो मासिक सीमा पुगेको छ। एक प्रशासकले यसलाई AI सेटिङहरूमा बढाउन सक्छन्।','Usage and cost'=>'प्रयोग र लागत','The log, limits and role permissions apply to AI used through: %s.'=>'लग, सीमाहरू र भूमिकाहरूका अनुमतिहरू %s मार्फत प्रयोग हुने AI मा लागू हुन्छन्।','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'लागतहरू अनुमानित हुन्, प्रकाशित मूल्यहरूबाट गणना गरिएका हुन्; कुनै अज्ञात मूल्य भएको मोडललाई शून्य मानिन्छ।','This month: %1$s requests, about %2$s.'=>'यो महिना: %1$s अनुरोधहरू, करिब %2$s।','When'=>'कहिले','Who'=>'को','Used for'=>'को लागि प्रयोग गरिएको','Model'=>'मोडल','Tokens in / out'=>'टोकन इन / आउट','About'=>'बारेमा','Result'=>'नतिजा','No AI requests have been made yet.'=>'अहिले सम्म कुनै पनि AI अनुरोधहरू गरिएका छैनन्।','Done'=>'सम्पन्न भयो','Limits and permissions'=>'सीमाहरू र अनुमतिहरू','Monthly spending limit (US dollars)'=>'मासिक खर्च सीमा (US डलर)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'कुनै सीमा नराख्न खाली छोड्नुहोस्। अनुमानित लागत यो सीमामा पुगेपछि बाँकी महिनाको लागि AI रोकिन्छ।','Monthly request limit'=>'मासिक अनुरोध सीमा','Leave empty for no limit.'=>'कुनै सीमा नराख्न खाली छोड्नुहोस्।','Who may use AI'=>'कसले एआई प्रयोग गर्न सक्छ','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'प्लगइनका सुविधाहरू प्रयोग गर्न सक्ने सबैलाई एआई प्रयोग गर्न दिनको लागि कुनै पनि नलगाउनुहोस्। प्रशासकहरूले यसलाई सधैँ प्रयोग गर्न सक्छन्।','Save limits and permissions'=>'सीमा र अनुमतिहरू सुरक्षित गर्नुहोस्','Limits and permissions saved.'=>'सीमाहरू र अनुमतिहरू सुरक्षित गरियो।','Content'=>'सामग्री','Not found.'=>'फेला परेन।','%s joined the chat.'=>'%s च्याटमा जोडिनुभयो।','Type a reply first.'=>'पहिले एउटा उत्तर टाइप गर्नुहोस्।','The chat has ended. Thank you for contacting us.'=>'च्याट समाप्त भएको छ। हामीलाई सम्पर्क गर्नुभएकोमा धन्यवाद।','You are chatting with the assistant again.'=>'तपाईं फेरि सहायकसँग कुराकानी गर्दै हुनुहुन्छ।','This conversation is now ticket #%d. We will reply by email.'=>'यो कुराकानी अब टिकट #%d बनेको छ। हामी इमेलमार्फत जवाफ दिनेछौं।','Type a question first.'=>'पहिले एउटा प्रश्न टाइप गर्नुहोस्।','The whole site is being read again in the background.'=>'पूरा साइट पृष्ठभूमिमा फेरि पढिँदैछ।','Meanings are being rebuilt in the background.'=>'पृष्ठभूमिमा अर्थहरू पुनः निर्माण गरिँदैछन्।','Submit a ticket form'=>'टिकट फारम पेश गर्नुहोस्','Heading'=>'शीर्षक','Default subject'=>'पूर्वनिर्धारित विषय','Button text'=>'बटनको पाठ','Show the subject field (yes or no)'=>'विषय क्षेत्र देखाउनुहोस् (हो वा होइन)','My support requests'=>'मेरो समर्थन अनुरोधहरू','Chat button'=>'च्याट बटन','Chat with us'=>'हामीसँग कुराकानी गर्नुहोस्','Support'=>'समर्थन','Thank you. Your request is ticket #%d. We have emailed you a link to follow it.'=>'धन्यवाद। तपाईंको अनुरोध टिकट #%d हो। यसलाई पछ्याउन हामीले तपाईंलाई लिङ्क इमेल गरेका छौँ।','Your reply has been sent.'=>'तपाईंको जवाफ पठाइएको छ।','If there is a request under that address, we have emailed you a new link.'=>'यदि त्यो ठेगानामा कुनै अनुरोध छ भने, हामीले तपाईंलाई नयाँ लिङ्क इमेल गरेका छौँ।','Something went wrong. Please check the form and try again.'=>'केही गडबडी भयो। कृपया फारम जाँच गरेर फेरि प्रयास गर्नुहोस्।','Your message could not be sent.'=>'तपाईंको सन्देश पठाउन सकिएन।','You are sending messages too quickly. Please wait a little and try again.'=>'तपाईंले धेरै छिटो सन्देशहरू पठाउँदै हुनुहुन्छ। कृपया अलिकति पर्खनुहोस् र फेरि प्रयास गर्नुहोस्।','Please agree to the privacy notice to send your request.'=>'तपाईंको अनुरोध पठाउन कृपया गोपनीयता सूचनामा सहमति जनाउनुहोस्।','Please complete the check to show you are not a robot.'=>'तपाईं रोबोट हुनुहुन्न भनी प्रमाणित गर्न कृपया जाँच पूरा गर्नुहोस्।','Sign in to see your support requests.'=>'तपाईंको समर्थन अनुरोधहरू हेर्न लग इन गर्नुहोस्।','Your name'=>'तपाईंको नाम','Your email'=>'तपाईंको इमेल','Subject'=>'विषय','Which order is this about?'=>'यो अर्डर कुन हो?','Not about an order'=>'अर्डरको बारेमा होइन','How can we help?'=>'हामी कसरी मद्दत गर्न सक्छौं?','Privacy policy'=>'गोपनीयता नीति','Send request'=>'अनुरोध पठाउनुहोस्','All requests'=>'सबै अनुरोधहरू','Your support requests'=>'तपाईंका समर्थन अनुरोधहरू','You have no support requests yet.'=>'तपाईंसँग अहिलेसम्म कुनै पनि सहयोग अनुरोधहरू छैनन्।','Updated'=>'अद्यावधिक गरिएको','New request'=>'नयाँ अनुरोध','This link has expired. Enter your email address and we will send you a new one.'=>'यो लिङ्कको म्याद समाप्त भएको छ। आफ्नो इमेल ठेगाना प्रविष्ट गर्नुहोस् र हामी तपाईंलाई नयाँ पठाउनेछौँ।','This link is not valid. Enter your email address and we will send you a link to your requests.'=>'यो लिङ्क मान्य छैन। आफ्नो इमेल ठेगाना प्रविष्ट गर्नुहोस् र हामी तपाईंलाई तपाईंको अनुरोधहरूको लिङ्क पठाउनेछौं।','Email me a new link'=>'मलाई नयाँ लिङ्क इमेल गर्नुहोस्','Request #%1$d: %2$s'=>'अनुरोध #%1$d: %2$s','Status:'=>'स्थिति:','Your reply'=>'तपाईंको जवाफ','Send reply'=>'उत्तर पठाउनुहोस्','You'=>'तपाईं','Submit a ticket'=>'टिकट पेस गर्नुहोस्','Add to Menu'=>'मेनुमा थप्नुहोस्','Create the support page on the Zinn® Chat setup screen to add a "Submit a ticket" link.'=>'Zinn® Chat सेटअप स्क्रिनमा "टिकट पेश गर्नुहोस्" लिङ्क थप्नको लागि समर्थन पृष्ठ सिर्जना गर्नुहोस्।','[#%1$d] We have your request: %2$s'=>'[#%1$d] हामीलाई तपाईंको अनुरोध प्राप्त भएको छ: %2$s','Thank you for contacting us. We have received your request and will reply as soon as we can.'=>'हामीलाई सम्पर्क गर्नुभएकोमा धन्यवाद। हामीले तपाईंको अनुरोध प्राप्त गरेका छौं र सकेसम्म चाँडो जवाफ दिनेछौं।','View your request'=>'तपाईंको अनुरोध हेर्नुहोस्','[#%1$d] New ticket: %2$s'=>'[#%1$d] नयाँ टिकट: %2$s','Open the ticket'=>'टिकट खोल्नुहोस्','[#%1$d] New reply: %2$s'=>'[#%1$d] नयाँ जवाफ: %2$s','You can reply on the page below.'=>'तपाईं तलको पृष्ठमा उत्तर दिन सक्नुहुन्छ।','View and reply'=>'हेर्नुहोस् र उत्तर दिनुहोस्','[#%1$d] Customer replied: %2$s'=>'[#%1$d] ग्राहकले जवाफ दिए: %2$s','A visitor is waiting in chat #%d'=>'च्याट #%d मा एक आगन्तुक प्रतीक्षा गर्दै छन्','A visitor asked to talk to a person and is waiting for an answer.'=>'एक आगन्तुकले व्यक्तितसँग कुरा गर्न आग्रह गरेका छन् र उत्तरको प्रतीक्षा गरिरहेका छन्।','Answer now'=>'अहिले नै जवाफ दिनुहोस्','Your chat with %s'=>'%s सँगको तपाईंको कुराकानी','[#%d] Your link to your request'=>'[#%d] तपाईंको अनुरोधको लिङ्क','Here is a new link to your request. The old one no longer works.'=>'तपाईंको अनुरोधका लागि यहाँ नयाँ लिङ्क छ। पुरानो लिङ्क अब काम गर्दैन।','From: %s'=>'कसबाट: %s','a visitor'=>'एक आगन्तुक','Zinn® Chat chats and support tickets'=>'Zinn® Chat च्याटहरू र सहयोग टिकटहरू','Chats'=>'चटहरू','Started'=>'सुरु गरिएको छ','Name'=>'नाम','Email'=>'इमेल','Page'=>'पृष्ठ','Messages'=>'सन्देशहरू','Support tickets'=>'समर्थन टिकटहरू','Ticket'=>'टिकट','Opened'=>'खोलिएको','When you use the chat or submit a support request, we store your messages, the name and email address you give us, the page you were on and a coded form of your IP address, so that we can answer you and keep a record of your request.'=>'जब तपाईं कुराकानी प्रयोग गर्नुहुन्छ वा समर्थन अनुरोध पेश गर्नुहुन्छ, तब हामी तपाईंलाई जवाफ दिन र तपाईंको अनुरोधको रेकर्ड राख्नका लागि तपाईंको सन्देशहरू, तपाईंले हामीलाई दिनुभएको नाम र इमेल ठेगाना, तपाईं कुन पृष्ठमा हुनुहुन्थ्यो र तपाईंको IP ठेगानाको एक कोड गरिएको रूप भण्डारण गर्छौं।','If our AI assistant answers you, your message and passages from this website are sent to the AI provider we use to produce the answer.'=>'यदि हाम्रो एआई सहायकले तपाईलाई उत्तर दिन्छ भने, उत्तर उत्पादन गर्न हामीले प्रयोग गर्ने एआई प्रदायककहाँ तपाईको सन्देश र यस वेबसाइटका अंशहरू पठाइन्छ।','This chat has ended.'=>'यो च्याट समाप्त भएको छ।','The chat is not available right now.'=>'च्याट अहिले उपलब्ध छैन।','Please type a message.'=>'कृपया एउटा सन्देश टाइप गर्नुहोस्।','Please agree to the privacy notice to start the chat.'=>'कुराकानी सुरु गर्न कृपया गोपनीयता सूचनामा सहमत हुनुहोस्।','You have started too many chats today. Please try again tomorrow or send us a ticket.'=>'तपाईंले आज धेरै च्याटहरू सुरु गर्नुभएको छ। कृपया भोलि फेरि प्रयास गर्नुहोस् या हामीलाई टिकट पठाउनुहोस्।','The chat could not be started. Please try again.'=>'च्याट सुरु हुन सकेन। कृपया पुनः प्रयास गर्नुहोस्।','Nobody can answer in chat right now. Leave your email address and we will reply by email.'=>'अहिले च्याटमा कोही पनि उत्तर दिन सक्दैनन्। आफ्नो इमेल ठेगाना छोड्नुहोस्, हामी इमेल मार्फत जवाफ दिनेछौँ।','The assistant cannot answer right now. You can ask for a person or leave us a message.'=>'सहायकले अहिले उत्तर दिन सक्दैन। तपाईंले कुनै व्यक्तिको लागि अनुरोध गर्न सक्नुहुन्छ वा हामीलाई सन्देश छोड्न सक्नुहुन्छ।','We are putting you through to a person. Please stay on this page.'=>'हामी तपाईंलाई एक व्यक्तितर्फ जोड्दैछौं। कृपया यसै पृष्ठमा रहनुहोस्।','Tickets are not available right now.'=>'अहिले टिकटहरू उपलब्ध छैनन्।','Visitor'=>'आगन्तुक','Team'=>'टिम','Chat so far:'=>'अहिलेसम्मको कुराकानी:','Thank you. Your request is ticket #%d and we will reply by email.'=>'धन्यवाद। तपाईंको अनुरोध टिकट #%d हो र हामी इमेल मार्फत जवाफ दिनेछौं।','Please enter a valid email address.'=>'कृपया वैध इमेल ठेगाना प्रविष्ट गर्नुहोस्।','This link is not valid.'=>'यो लिङ्क मान्य छैन।','This link has expired. We can email you a new one.'=>'यो लिङ्कको म्याद समाप्त भएको छ। हामी तपाईँलाई नयाँ लिङ्क इमेल गर्न सक्छौँ।','You cannot see this ticket.'=>'तपाईं यो टिकट हेर्न सक्नुहुन्न।','Hi! Ask me anything about this site. I answer from its own pages, and I can put you through to a person.'=>'नमस्ते! यस साइटको बारेमा मलाई केही पनि सोध्नुहोस्। म यसकै पृष्ठहरूबाट जवाफ दिन्छु, र म तपाईंलाई कुनै व्यक्तिसँग सम्पर्क गराउन सक्छु।','Hi! How can we help? Send us a message and we will get back to you.'=>'नमस्ते! हामी कसरी मद्दत गर्न सक्छौं? हामीलाई सन्देश पठाउनुहोस् र हामी तपाईंकहाँ फर्कनेछौं।','Nobody is online right now. Leave your question and email address and we will reply by email.'=>'अहिले कोही पनि अनलाइन छैनन्। आफ्नो प्रश्न र इमेल ठेगाना छोड्नुहोस्, हामी इमेल मार्फत जवाफ दिनेछौं।','We keep this conversation so we can answer you.'=>'हामी तपाईंलाई जवाफ दिन सकौं भनेर यो कुराकानी सुरक्षित राख्छौं।','Please enter a valid email address so we can reply.'=>'कृपया वैध इमेल ठेगाना प्रविष्ट गर्नुहोस् ताकि हामी जवाफ दिन सकौं।','Please describe what you need help with.'=>'कृपया तपाईलाई के मा सहयोग चाहिएको छ वर्णन गर्नुहोस्।','The ticket could not be saved. Please try again.'=>'टिकट सुरक्षित गर्न सकिएन। कृपया फेरि प्रयास गर्नुहोस्।','That ticket does not exist.'=>'त्यो टिकट अवस्थित छैन।','The reply is 